// 1. Obtener los datos directamente del input
const inputData = $input.item.json;
const body = inputData.body || {};
const lead = body.lead || {}; 

// 2. Extraer el objeto del nuevo vendedor de forma segura
const vendedorNuevo = body.vendedor_nuevo || {};

// Extraer y formatear el nombre del NUEVO vendedor (Primera Letra Mayúscula)
let nameRaw = vendedorNuevo.nombre || body.vendedor || "Nuestro Equipo";
const name = nameRaw
  .toLowerCase()
  .split(' ')
  .map(word => word.charAt(0).toUpperCase() + word.slice(1))
  .join(' ');

// 3. Extraer el seller_id del NUEVO vendedor (según la captura es 21)
const seller_id = vendedorNuevo.seller_id || lead.seller_id || 0;
const asignacion = lead.asignacion || 0; 

// 4. Lógica de saneamiento de WhatsApp
let telefono = (lead.telefono || "").toString().replace(/\D/g, "");
if (telefono.startsWith("0")) {
  telefono = telefono.substring(1);
}
if (!telefono.startsWith("58")) {
  telefono = "58" + telefono;
}

// Mensaje institucional orientado al aliado B2B
const mensaje = `Hola, soy ${name} de Supricom. El equipo de marketing me envió tus datos para darte atención prioritaria. Mi objetivo es asegurar que tu negocio cuente con el respaldo de un mayorista en tecnología que necesitas.`;
const whatsappLink = `https://wa.me/${telefono}?text=${encodeURIComponent(mensaje)}`;

// 5. Retornar el objeto con los mapeos correctos en minúsculas
return [{
  json: {
    evento: body.evento || null,
    vendedor: name,
    seller_id: parseInt(seller_id) || 0,
    AsignacionActual: parseInt(asignacion) || 0,
    WhatsAppLink: whatsappLink,

    // Mantener la información del vendedor anterior si se requiere en auditorías futuras
    vendedor_anterior_id: body.vendedor_anterior?.seller_id || null,
    vendedor_anterior_nombre: body.vendedor_anterior?.nombre || null,

    // Mapeo del lead en minúsculas
    nombre_contacto: lead.nombre_contacto || null,
    empresa: lead.empresa || null,
    telefono_local: lead.telefono || null,
    rif: lead.rif || null,
    ubicacion_estado: lead.ubicacion_estado || null,
    ubicacion_detail: lead.ubicacion_detalle || null,
    canal_origen: lead.canal_origen || null,
    campana: lead.campana || null,
    status: lead.status || null
  }
}];

